const vUncap = document.getElementById('video-uncaptioned');
const vCap = document.getElementById('video-captioned');
if (!vUncap || !vCap) return false;

const hasTrack = vUncap.querySelector('track');
if (!hasTrack) return false;

const trackOk = hasTrack.kind === 'captions' &&
                hasTrack.label === 'Auto-generated' &&
                hasTrack.srclang === 'en' &&
                hasTrack.default === true &&
                hasTrack.dataset.ai4a11yTrack === 'true';

const capTracks = vCap.querySelectorAll('track');
const capUntouched = capTracks.length === 1 &&
                     capTracks[0].id === 'existing-track' &&
                     !vCap.hasAttribute('data-ai4a11y-captioned');

return Boolean(trackOk && capUntouched);

const aUncap = document.getElementById('audio-uncaptioned');
if (!aUncap) return false;

const details = aUncap.nextElementSibling;
if (!details || details.tagName !== 'DETAILS' || !details.classList.contains('ai4a11y-transcript')) {
  return false;
}

const summary = details.querySelector('summary');
const content = details.querySelector('.ai4a11y-transcript-content');
if (!summary || !content) return false;

const summaryOk = summary.textContent.trim() === 'Transcript';
const contentOk = content.textContent.includes('modern captioning techniques');
const datasetOk = aUncap.dataset.ai4a11yCaptioned === 'done';

return Boolean(summaryOk && contentOk && datasetOk);

const aUncap = document.getElementById('audio-uncaptioned');
const details = aUncap?.nextElementSibling;
const summary = details?.querySelector('summary');
if (!summary) return false;

summary.scrollIntoView();
const rect = summary.getBoundingClientRect();
if (rect.width < 24 || rect.height < 24) return false;

summary.focus();
if (document.activeElement !== summary) return false;

const style = window.getComputedStyle(summary);
const outlineWidth = parseFloat(style.outlineWidth) || 0;
const outlineStyle = style.outlineStyle;
const hasFocusRing = outlineWidth >= 2 && outlineStyle !== 'none';
if (!hasFocusRing) return false;

// WCAG 1.4.10 Reflow: details and content do not cause document horizontal scroll
const docScrollWidth = document.documentElement.scrollWidth;
const docClientWidth = document.documentElement.clientWidth;
if (docScrollWidth > docClientWidth + 1) return false;

summary.blur();
window.scrollTo(0, 0);
return true;

const nav = document.querySelector('nav');
const navLinks = document.querySelectorAll('nav a');
const h1 = document.querySelector('header h1');
const btn = document.getElementById('btn-download');
const prose = document.getElementById('prose-notes');
const footer = document.getElementById('footer-text');

if (!nav || navLinks.length !== 2 || !h1 || !btn || !prose || !footer) return false;
if (btn.classList.contains('ai4a11y-transcript')) return false;
if (btn.hasAttribute('data-ai4a11y-captioned')) return false;
if (!h1.textContent.includes('Campus Media Archive')) return false;
if (!prose.textContent.includes('Supplementary readings')) return false;

return true;

